def is_unimodal(lst):
    n = len(lst)
    if n < 3:
        return False
    i = 0
    while i + 1 < n and lst[i] < lst[i + 1]:
        i += 1
    if i == 0 or i == n - 1:
        return False
    while i + 1 < n and lst[i] > lst[i + 1]:
        i += 1
    return i == n - 1

def plateau_count(lst):
    n = len(lst)
    count = 0
    i = 0
    while i < n:
        j = i
        while j + 1 < n and lst[j + 1] == lst[i]:
            j += 1
        if j - i + 1 >= 2:
            count += 1
        i = j + 1
    return count

