def longest_alternating_run(lst):
    n = len(lst)
    if n == 0:
        return 0
    best = 1
    cur = 1
    prev_dir = 0
    for i in range(1, n):
        if lst[i] > lst[i - 1]:
            d = 1
        elif lst[i] < lst[i - 1]:
            d = -1
        else:
            d = 0
