def is_rotation(a, b):
    if len(a) != len(b):
        return False
    if not a:
        return True
    doubled = a + a
    n = len(a)
    for k in range(n):
        if doubled[k:k + n] == b:
            return True
    return False

def rotation_offset(a, b):
    n = len(a)
    if n != len(b):
        return -1
    if n == 0:
        return 0
    for k in range(n):
        if a[k:] + a[:k] == b:
            return k
    return -1
